import pandas as pd
import numpy as np
import itertools

def task_func(data_list=None):
    if data_list is None:
        data_list = [('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]

    if not data_list:
        return pd.DataFrame(columns=['Mean Value'])

    # Determine the maximum length of tuples
    max_len = max(len(t) for t in data_list) if data_list else 0

    if max_len == 0:
        return pd.DataFrame(columns=['Mean Value'])

    # Collect numeric values for each position
    position_values = [[] for _ in range(max_len)]

    for tup in data_list:
        for i, val in enumerate(tup):
            if isinstance(val, (int, float, np.integer, np.floating)):
                # Check that it's not a boolean (bool is subclass of int)
                if not isinstance(val, bool):
                    position_values[i].append(float(val))

    # Calculate means
    means = []
    for i in range(max_len):
        if position_values[i]:
            mean_val = np.mean(position_values[i])
        else:
            mean_val = np.nan
        means.append(mean_val)

    # Create index
    index = [f'Position {i}' for i in range(max_len)]

    # Create DataFrame
    df = pd.DataFrame({'Mean Value': means}, index=index)

    return df

